D.SpellTexts[36683]={Description={["50c80d7f33bd02d6:109"]="如果玩家使用邪恶雕像时所在的食人魔建筑物已经被诅咒，则召唤一个被诅咒的幽魂来攻击玩家。"}}
D.SpellTexts[36686]={Description={["c54a21b7a96fc852:129"]="将这些物品转化为暗影布的过程只能在影月谷的暗影祭坛进行。暗影祭坛的能量一段时间内只能够进行一次转化。"}}
