D.SpellTexts[44856]={Description={["7accd96c36b6ec6d:265"]="使玩家、玩家所在小队及其宠物进入另一个相位，在所有未改变相位的生物面前隐形，并且可以看到巴什伊尔码头的法力晶格。所有队友和宠物都必须保持在施法者身边100码范围内才能维持相位改变状态。只能在巴什伊尔码头使用这种设备。"},Aura={["88e64c115fe55fb8:11"]="相位转换。"}}
