D.SpellTexts[45278]={Description={["63e60f7c9068d9a9:213"]="穿上国王姆嘎姆嘎的备用鱼人服。只能在冬鳞村和冬鳞洞穴内使用，且只有敌对的冬鳞鱼人会被你欺骗。许多行为，包括战斗和施放增益法术，都会导致伪装失效。"},Aura={["7020c6b26b3e2887:69"]="与冬鳞村和冬鳞洞穴的冬鳞鱼人友善。"}}
