D.SpellTexts[47469]={Description={["8a6ccaf6754b5343:45"]="控制魔法焦点，并阅读该处的读数。"}}
D.SpellTexts[47473]={Aura={["aca8f2e347f017d4:130"]="这里的魔法能量被用来极大地强化其使用者的力量。能量流继续朝东边流去。"}}
